'AC8.13.50'; import pytest; from tests.e2e.auth_cookie import build_auth_cookie, build_runner_browser_session
def test_AC8_13_50_auth_cookie_uses_domain_path_for_deployed_host() -> None:
    cookie = build_auth_cookie('https://report-staging.zitian.party', 'test-token'); assert cookie == {'name': 'finance_access_token', 'value': 'test-token', 'domain': 'report-staging.zitian.party', 'path': '/', 'httpOnly': True, 'sameSite': 'Lax', 'secure': True}; _m1_cookie = build_auth_cookie('http://localhost:3000', 'test-token'); assert _m1_cookie == {'name': 'finance_access_token', 'value': 'test-token', 'domain': 'localhost', 'path': '/', 'httpOnly': True, 'sameSite': 'Lax'}
    with pytest.raises(ValueError, match='APP_URL must include a hostname'): build_auth_cookie('not-a-url', 'test-token')
    _m3_app_url = 'https://report-staging.zitian.party'; _m3_cookie, _m3_script = build_runner_browser_session({'user_email': 'qa@test.example.com', 'user_data': {'access_token': 'tok', 'id': '42'}}, _m3_app_url); assert _m3_cookie == build_auth_cookie(_m3_app_url, 'tok'); assert 'localStorage.setItem(\'finance_user_id\', "42");' in _m3_script; assert 'localStorage.setItem(\'finance_user_email\', "qa@test.example.com");' in _m3_script; _m4__, _m4_script = build_runner_browser_session({'user_email': 'qa@test.example.com', 'user_data': {'access_token': 'tok', 'user': {'id': 7}}}, 'http://localhost:3000'); assert 'localStorage.setItem(\'finance_user_id\', "7");' in _m4_script
@pytest.mark.parametrize('auth_context', [{'user_email': 'qa@test.example.com', 'user_data': {'id': '1'}}, {'user_email': 'qa@test.example.com', 'user_data': {'access_token': 'tok'}}, {'user_data': {'access_token': 'tok', 'id': '1'}}, {}], ids=['no-token', 'no-user-id', 'no-email', 'empty'])
def test_AC8_13_50_runner_browser_session_rejects_incomplete_context(auth_context: dict) -> None:
    with pytest.raises(ValueError, match='Invalid auth context for browser session injection'): build_runner_browser_session(auth_context, 'http://localhost:3000')
